const $ = (selector) => document.querySelector(selector);
const esc = (value) => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));

async function api(path, options = {}) {
  if ((options.method || 'GET').toUpperCase() === 'POST') {
    if (path === '/api/finance-workflow/vouchers') path = '/api/finance-workflow/vouchers-enhanced';
    else if (/^\/api\/finance-workflow\/vouchers\/\d+\/approve(?:\?|$)/.test(path)) path = path.replace('/approve','/approve-enhanced');
    else if (path === '/api/finance-workflow/settlements') path = '/api/finance-workflow/settlements-enhanced';
    else if (/^\/api\/finance-workflow\/settlements\/\d+\/post(?:\?|$)/.test(path)) path = path.replace('/post','/post-enhanced');
  }
  const requestScreen = state.screen;
  const headers = new Headers(options.headers || {});
  const token = localStorage.getItem('erp-auth-token');
  if (token) headers.set('Authorization', `Bearer ${token}`);
  const requestedSource = (() => { try { return new URL(path, location.origin).searchParams.get('source_database') || currentDatabase; } catch (_) { return currentDatabase; } })().toUpperCase();
  const requestedContext = (companyContexts || []).find(row => String(row.source_database).toUpperCase() === requestedSource);
  headers.set('X-Source-Database', requestedSource);
  headers.set('X-ERP-Context-Key', String(currentCompanyContext?.source_database || requestedSource).toUpperCase());
  headers.set('X-Company-Id', requestedContext?.company_id || requestedSource);
  if (currentDepartmentCode && !path.startsWith('/api/auth/')) headers.set('X-ERP-Department-Code', currentDepartmentCode);
  if (currentDepartmentCode && path.startsWith('/api/') && !path.startsWith('/api/auth/') && !path.startsWith('/api/access-')) {
    try {
      const url = new URL(path, location.origin);
      if (!url.searchParams.has('department_code')) url.searchParams.set('department_code', currentDepartmentCode);
      path = `${url.pathname}${url.search}${url.hash}`;
    } catch (_) { /* 使用原始路徑；標頭仍會提供目前部門 */ }
  }
  const response = await fetch(path, { ...options, headers });
  const body = await response.json().catch(() => ({}));
  if (!response.ok || body.ok === false) throw new Error(body.error || `HTTP ${response.status}`);
  // 使用者切換分頁後，舊分頁的慢查詢不可再回寫目前畫面，避免表頭與資料列錯位。
  if (requestScreen !== state.screen) return await new Promise(() => {});
  let data = body.data ?? body;
  const recentList = /\/(documents|order-changes|open-items|settlements|source-documents|returns|pending-inspections|requisition-maintenance|progress|open-orders|notes)(\/|\?|$)/.test(path);
  if ((!options.method || options.method === 'GET') && recentList && Array.isArray(data)) {
    const dateFields = ['document_date','change_date','settlement_date','return_date','receipt_date','requisition_date','order_date','created_at'];
    data = [...data].sort((a,b) => {
      const av = dateFields.map(key => a?.[key]).find(Boolean) || '';
      const bv = dateFields.map(key => b?.[key]).find(Boolean) || '';
      return String(bv).localeCompare(String(av)) || Number(b?.id || 0) - Number(a?.id || 0);
    }).slice(0,10);
  }
  return data;
}

function toast(message, error = false) {
  const el = document.createElement('div'); el.className = `toast ${error ? 'error' : ''}`; el.textContent = message;
  document.body.appendChild(el); setTimeout(() => el.remove(), 3200);
}

function renderSidebar() {
  const visible = getVisibleModules();
  $('#sidebar').innerHTML = visible.map(module => `<div class="group"><div class="group-title">${esc(module.name)}</div><button class="module ${state.module === module.id ? 'active' : ''}" data-module="${module.id}"><span class="id">${module.id}</span><span class="name">${esc(module.name)}</span></button></div>`).join('');
  document.querySelectorAll('[data-module]').forEach(button => button.onclick = () => { state.module = button.dataset.module; state.screen = visible.find(x => x.id === state.module).screens[0][0]; renderAll(); });
}

function renderTabs() {
  const visible = getVisibleModules();
  const module = visible.find(x => x.id === state.module) || visible[0];
  if (!module) { $('#tabbar').innerHTML = ''; return; }
  $('#tabbar').innerHTML = module.screens.map(([id, title]) => `<button class="tab ${id === state.screen ? 'active' : ''}" data-screen="${id}">${esc(title)}</button>`).join('');
  document.querySelectorAll('[data-screen]').forEach(button => button.onclick = () => { state.screen = button.dataset.screen; renderAll(); });
}

function renderAll() {
  const visible = getVisibleModules();
  if (visible.length && !visible.some(module => module.id === state.module && module.screens.some(([id]) => id === state.screen))) {
    state.module = visible[0].id; state.screen = visible[0].screens[0][0];
  }
  document.body.classList.toggle('architecture-mode', state.module === 'ARCH');
  renderSidebar(); renderTabs(); renderScreen(); enforceCompanyContextFields();
  $('#breadcrumb').textContent = `${visible.find(x => x.id === state.module)?.name || ''} / ${getTitle(state.screen)}`;
}

function getVisibleModules() {
  if (typeof canViewFeature !== 'function') return modules;
  return modules.map(module => ({ ...module, screens:module.screens.filter(([id]) => canViewFeature(id)) })).filter(module => module.screens.length);
}

function getTitle(screen) {
  for (const module of modules) for (const [id, title] of module.screens) if (id === screen) return title;
  return screen;
}

function targetDatabaseLabel() {
  return currentCompanyContext?.target_database || 'inventory_erp';
}

function renderScreen() {
  const config = masterConfigs[state.screen];
  if (config) return renderMasterScreen(state.screen, config);
  if (state.screen === 'document-natures') return renderDocumentNatures();
  if (state.screen === 'basicdata') return renderBasicData();
  if (state.screen === 'source-mappings') return renderSourceMappings();
  if (state.screen === 'import-monitor') return renderImportMonitor();
  if (state.screen === 'data-quality') return renderImportDataQuality();
  if (state.screen === 'common-parameters') return renderCommonParameters();
  if (state.screen === 'inventory-opening') return renderInventoryOpening();
  if (state.screen.startsWith('inventory-') && ['inventory-document-types','inventory-transactions','inventory-transfers','inventory-temporary','inventory-stocktake','inventory-posting','inventory-reversals','inventory-new-balance','inventory-new-ledger'].includes(state.screen)) return renderInventoryWorkflow(state.screen);
  if (state.module === 'PUR') return renderProcurementScreen(state.screen);
  if (state.module === 'SAL') return renderSalesScreen(state.screen);
  if (state.module === 'FIN') return renderFinanceScreen(state.screen);
  if (state.screen === 'operations-reports') return renderOperationsReports();
  if (state.module === 'RPT') return renderFlowAuditScreen(state.screen);
  if (state.module === 'ARCH') return renderArchitectureScreen();
  $('#canvas').innerHTML = `<section class="screen"><div class="screen-head"><h2>${esc(getTitle(state.screen))}</h2><button class="btn" id="refreshScreen">重新整理</button></div><div class="screen-body"><div class="desc">此作業已保留流程位置，後續會依 iSM 文件接續資料表與單據欄位。</div><div class="empty-hint">目前尚未載入資料。</div></div></section>`;
  $('#refreshScreen').onclick = refresh;
}

const documentNatureModuleNames={PUR:'採購',SAL:'銷售',AR:'應收',AP:'應付',BANK:'銀行／票據',GL:'總帳'};
const documentNatureKinds={requisition:'請購',purchase_order:'採購',receipt:'進貨',purchase_return:'採購退貨／折讓',quotation:'報價',sales_order:'訂單',shipment:'銷貨',sales_return:'銷退／折讓',settlement:'結帳／憑單',collection:'收款／沖銷',payment:'付款／沖銷',note:'票據',journal:'手動傳票',auto_journal:'自動分錄傳票',deposit:'銀行存入',withdrawal:'銀行提領'};
function renderDocumentNatures(){
  $('#canvas').innerHTML=`<section class="screen"><div class="screen-head"><h2>單據／分錄性質</h2><span class="code">inventory_erp</span><button class="btn" id="documentNatureReload" type="button">重新整理</button></div><div class="screen-body"><div class="desc">依目前公司別／資料來源維護採購、銷售、應收、應付、票據與總帳的單據性質。來源 ERP 僅供同步參考；新增與修改寫入目前公司的 inventory_erp。SH／SC 會依 source_database 分開保存，不會共用規則。</div><form id="documentNatureForm" class="form"><div class="row c4">${selectField('module_code','模組','<option value="PUR">採購</option><option value="SAL">銷售</option><option value="AR">應收</option><option value="AP">應付</option><option value="BANK">銀行／票據</option><option value="GL">總帳</option>')}${selectField('document_kind','單據種類',Object.entries(documentNatureKinds).map(([k,v])=>`<option value="${k}">${v}</option>`).join(''))}${field('nature_code','性質代碼','text','required')}${field('type_code','單別代號','text','required')}${field('type_name','名稱','text','required')}${field('type_full_name','單據全名')}${field('number_prefix','單號前綴')}${selectField('numbering_method','編碼方式','<option value="daily">日編</option><option value="monthly">月編</option><option value="sequence">流水號</option><option value="manual">手動編號</option>')}${field('year_digits','年碼數','number','min="1" max="4" value="4"')}${field('serial_digits','流水號碼數','number','min="1" max="9" value="4"')}${selectField('requires_approval','需要核准','<option value="1">是</option><option value="0">否</option>')}${selectField('auto_confirm','存檔自動確認','<option value="0">否</option><option value="1">是</option>')}${selectField('direct_settlement','直接結帳／立帳','<option value="0">否</option><option value="1">是</option>')}${selectField('settlement_mode','結帳方式','<option value="batch">批次／月結</option><option value="whole">整張直接結帳</option><option value="per_document">逐筆直接結帳</option><option value="manual">手動</option>')}${selectField('require_source_document','必須有來源單','<option value="0">否</option><option value="1">是</option>')}${field('source_document_kind','來源單據種類')}${selectField('inventory_effect','庫存影響','<option value="none">不影響</option><option value="in">增加庫存</option><option value="out">減少庫存</option>')}${field('debit_account_code','借方科目代號')}${field('debit_account_name','借方科目名稱')}${field('credit_account_code','貸方科目代號')}${field('credit_account_name','貸方科目名稱')}${selectField('is_default','預設性質','<option value="0">否</option><option value="1">是</option>')}${selectField('is_active','狀態','<option value="1">啟用</option><option value="0">停用</option>')}${field('note','備註')}</div><button class="btn primary" id="documentNatureSave" type="submit">新增性質</button><button class="btn" id="documentNatureCancel" type="button" hidden>取消修改</button></form><div class="panel"><div class="panel-head"><span>目前公司別性質</span><select id="documentNatureModuleFilter"><option value="">全部模組</option><option value="PUR">採購</option><option value="SAL">銷售</option><option value="AR">應收</option><option value="AP">應付</option><option value="BANK">銀行／票據</option><option value="GL">總帳</option></select></div><div class="panel-body"><div class="table-wrap"><table class="grid"><thead><tr><th>模組／種類</th><th>性質／單別</th><th>名稱</th><th>編碼規則</th><th>核准／直接結帳</th><th>借方</th><th>貸方</th><th>來源／狀態</th><th>作業</th></tr></thead><tbody id="documentNatureRows"></tbody></table></div></div></div></div></section>`;
  const form=$('#documentNatureForm'), load=async()=>{try{const module=$('#documentNatureModuleFilter').value,qs=new URLSearchParams({source_database:currentDatabase});if(module)qs.set('module_code',module);const rows=await api(`/api/document-natures?${qs}`);window.documentNatureRows=rows;$('#documentNatureRows').innerHTML=rows.map(r=>`<tr><td>${esc(documentNatureModuleNames[r.module_code]||r.module_code)}／${esc(documentNatureKinds[r.document_kind]||r.document_kind)}</td><td>${esc(r.nature_code)}／${esc(r.type_code)}</td><td>${esc(r.type_name)}</td><td>${esc(r.number_prefix)}／${esc(r.numbering_method)}／${esc(r.year_digits)}+${esc(r.serial_digits)}</td><td>${r.requires_approval?'核准':'免核准'}／${r.direct_settlement?'直接':'批次'}</td><td>${esc(r.debit_account_code||'—')} ${esc(r.debit_account_name||'')}</td><td>${esc(r.credit_account_code||'—')} ${esc(r.credit_account_name||'')}</td><td>${esc(r.source_database)}／${esc(r.source_status)}／${r.is_active?'啟用':'停用'}</td><td><button class="btn small" data-document-nature-edit="${r.id}">修改</button><button class="btn small" data-document-nature-disable="${r.id}">隱藏</button></td></tr>`).join('')||'<tr><td colspan="9" class="empty-hint">目前公司別尚無單據性質</td></tr>';document.querySelectorAll('[data-document-nature-edit]').forEach(b=>b.onclick=()=>editDocumentNature(Number(b.dataset.documentNatureEdit)));document.querySelectorAll('[data-document-nature-disable]').forEach(b=>b.onclick=async()=>{try{await api(`/api/document-natures/${b.dataset.documentNatureDisable}?source_database=${encodeURIComponent(currentDatabase)}`,{method:'DELETE'});toast('單據性質已隱藏');load();}catch(e){toast(e.message,true);}});}catch(e){toast(e.message,true);}};
  form.onsubmit=async e=>{e.preventDefault();try{const data=Object.fromEntries(new FormData(form));data.source_database=currentDatabase;const id=form.dataset.editId;await api(id?`/api/document-natures/${id}`:'/api/document-natures',{method:id?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});toast(id?'單據／分錄性質已修改':'單據／分錄性質已新增');renderDocumentNatures();}catch(e){toast(e.message,true);}};
  $('#documentNatureReload').onclick=load;$('#documentNatureModuleFilter').onchange=load;$('#documentNatureCancel').onclick=()=>renderDocumentNatures();load();
}
function editDocumentNature(id){const row=(window.documentNatureRows||[]).find(x=>Number(x.id)===id),form=$('#documentNatureForm');if(!row||!form)return;form.dataset.editId=id;for(const[k,v]of Object.entries(row)){if(form.elements[k])form.elements[k].value=v??'';}form.elements.module_code.disabled=true;form.elements.document_kind.disabled=true;form.elements.type_code.readOnly=true;$('#documentNatureSave').textContent='儲存修改';$('#documentNatureCancel').hidden=false;form.scrollIntoView({behavior:'smooth',block:'start'});}

function renderInventoryOpening() {
  const today = new Date().toLocaleDateString('sv-SE', { timeZone:'Asia/Taipei' }).replaceAll('-', '');
  $('#canvas').innerHTML = `<section class="screen"><div class="screen-head"><h2>庫存開帳作業</h2><span class="code">INV-OPEN</span><button class="btn" id="refreshOpening">重新整理</button></div><div class="screen-body">
    <div class="desc">依期初開帳流程，從目前唯讀來源 ${esc(currentDatabase)} 帶入品號、庫別、庫存數量與金額，驗證、核准後寫入 ${esc(targetDatabaseLabel())}。</div>
    <form id="openingImportForm" class="form"><div class="row c3"><div class="field"><label>開帳日期（YYYYMMDD）</label><input name="opening_date" value="${today}" pattern="\d{8}" required></div><div class="field"><label>備註</label><input name="note" placeholder="例如：${esc(currentDatabase)} 首次庫存開帳"></div></div><button class="btn primary" type="submit">從目前來源建立開帳草稿</button></form>
    <div class="panel"><div class="panel-head"><span>開帳批次</span><button class="btn small" id="validateOpening" hidden>驗證</button><button class="btn small" id="approveOpening" hidden>核准</button><button class="btn small primary" id="postOpening" hidden>正式過帳</button></div><div class="panel-body" id="openingSummary"><div class="empty-hint">載入中…</div></div></div>
    <div class="panel" id="openingLineEditor" hidden><div class="panel-head">修正開帳明細</div><div class="panel-body"><form id="openingLineForm" class="form"><input type="hidden" name="line_id"><div class="row c3"><div class="field"><label>品號／庫別</label><input name="identity" readonly></div><div class="field"><label>庫存數量</label><input name="quantity" type="number" step="0.001" required></div><div class="field"><label>庫存金額</label><input name="amount" type="number" step="0.000001" required></div><div class="field"><label>修正備註</label><input name="note"></div></div><button class="btn primary" type="submit">儲存修正</button><button class="btn" id="cancelOpeningEdit" type="button">取消</button></form></div></div>
    <div class="panel"><div class="panel-head"><span>開帳明細</span><input id="openingKeyword" placeholder="品號、品名、庫別或錯誤"><button class="btn small" id="searchOpening" type="button">查詢</button></div><div class="panel-body"><div id="openingLineStatus" class="desc">載入中…</div><div class="table-wrap"><table class="grid"><thead><tr><th>狀態</th><th>品號</th><th>品名</th><th>庫別</th><th>儲位</th><th>數量</th><th>單位成本</th><th>金額</th><th>檢核訊息</th><th>操作</th></tr></thead><tbody id="openingRows"></tbody></table></div></div></div>
  </div></section>`;
  $('#refreshOpening').onclick = loadInventoryOpening; $('#searchOpening').onclick = loadInventoryOpening;
  $('#openingImportForm').onsubmit = importInventoryOpening; $('#openingLineForm').onsubmit = saveInventoryOpeningLine;
  $('#cancelOpeningEdit').onclick = () => { $('#openingLineEditor').hidden = true; };
  $('#validateOpening').onclick = () => runInventoryOpeningAction('validate');
  $('#approveOpening').onclick = () => runInventoryOpeningAction('approve');
  $('#postOpening').onclick = () => runInventoryOpeningAction('post');
  loadInventoryOpening();
}

async function loadInventoryOpening() {
  try {
    const keyword = $('#openingKeyword')?.value || '';
    const data = await api(`/api/inventory-opening?db=${encodeURIComponent(currentDatabase)}&keyword=${encodeURIComponent(keyword)}&limit=500`);
    inventoryOpeningState.batch = data.batch; inventoryOpeningState.lines = data.lines || [];
    if (!data.batch) {
      $('#openingSummary').innerHTML = '<div class="empty-hint">尚未建立庫存開帳草稿。</div>';
      $('#openingLineStatus').textContent = `請先從 ${currentDatabase} 建立開帳草稿。`; $('#openingRows').innerHTML = '<tr><td colspan="10" class="empty-hint">目前沒有資料</td></tr>'; return;
    }
    const b=data.batch;
    $('#openingSummary').innerHTML = `<div class="row c3"><div><strong>開帳單號</strong><br>${esc(b.opening_no)}</div><div><strong>狀態</strong><br>${esc(b.status)}</div><div><strong>開帳日期</strong><br>${esc(b.opening_date)}</div><div><strong>來源／匯入</strong><br>${b.source_rows}／${b.imported_rows} 筆</div><div><strong>錯誤／警告</strong><br>${b.error_rows}／${b.warning_rows} 筆</div><div><strong>數量／金額</strong><br>${Number(b.total_quantity).toLocaleString()}／${Number(b.total_amount).toLocaleString()}</div></div>`;
    $('#validateOpening').hidden = !['draft','draft_with_errors','validated'].includes(b.status);
    $('#approveOpening').hidden = b.status !== 'validated'; $('#postOpening').hidden = b.status !== 'approved';
    $('#openingLineStatus').textContent = `來源：${data.source}；目前顯示 ${data.lines.length} 筆（錯誤與警告優先）`;
    $('#openingRows').innerHTML = data.lines.map(row => `<tr><td>${esc(row.validation_status)}</td><td>${esc(row.item_code)}</td><td>${esc(row.item_name)}</td><td>${esc(row.warehouse_code)} ${esc(row.warehouse_name)}</td><td>${esc(row.location_code)}</td><td>${Number(row.quantity).toLocaleString()}</td><td>${Number(row.unit_cost).toLocaleString()}</td><td>${Number(row.amount).toLocaleString()}</td><td>${esc(row.validation_message || '')}</td><td><button class="btn small" type="button" data-opening-line="${row.id}">修改</button></td></tr>`).join('') || '<tr><td colspan="10" class="empty-hint">沒有符合條件的明細</td></tr>';
    document.querySelectorAll('[data-opening-line]').forEach(button => button.onclick = () => editInventoryOpeningLine(Number(button.dataset.openingLine)));
  } catch (error) { if ($('#openingLineStatus')) $('#openingLineStatus').textContent=error.message; }
}

async function importInventoryOpening(event) {
  event.preventDefault(); const body=Object.fromEntries(new FormData(event.currentTarget).entries());
  try { await api(`/api/inventory-opening/import?db=${encodeURIComponent(currentDatabase)}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}); toast(`${currentDatabase} 庫存已建立為 ${targetDatabaseLabel()} 開帳草稿`); await loadInventoryOpening(); } catch(error){toast(error.message,true);}
}

function editInventoryOpeningLine(id) {
  const row=inventoryOpeningState.lines.find(item=>Number(item.id)===id); if(!row)return;
  const form=$('#openingLineForm'); form.elements.line_id.value=id; form.elements.identity.value=`${row.item_code} / ${row.warehouse_code}`; form.elements.quantity.value=row.quantity; form.elements.amount.value=row.amount; form.elements.note.value=row.note||''; $('#openingLineEditor').hidden=false;
}

async function saveInventoryOpeningLine(event) {
  event.preventDefault(); const form=event.currentTarget; const id=form.elements.line_id.value; const batch=inventoryOpeningState.batch;
  try { await api(`/api/inventory-opening/${batch.id}/lines/${id}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({quantity:form.elements.quantity.value,amount:form.elements.amount.value,note:form.elements.note.value})}); toast('開帳明細已修正'); $('#openingLineEditor').hidden=true; await loadInventoryOpening(); } catch(error){toast(error.message,true);}
}

async function runInventoryOpeningAction(action) {
  const batch=inventoryOpeningState.batch; if(!batch)return;
  try { await api(`/api/inventory-opening/${batch.id}/${action}`,{method:'POST'}); toast(action==='validate'?'開帳驗證完成':action==='approve'?'開帳已核准':'開帳已正式過帳'); await loadInventoryOpening(); } catch(error){toast(error.message,true);}
}

