  if(mappingForm){mappingForm.onsubmit=async event=>{event.preventDefault();const data=Object.fromEntries(new FormData(mappingForm)),id=data.mapping_id;delete data.mapping_id;data.source_database=currentDatabase;data.is_active=1;data.reason=id?'修改客戶品號對照':'建立客戶品號對照';try{await api(`/api/sales-workflow/customer-item-mappings${id?`/${encodeURIComponent(id)}`:''}`,{method:id?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});toast(id?'客戶品號修改已儲存':'客戶品號已建立');resetMappingForm();loadAll();}catch(error){toast(error.message,true);}};$('#salesCustomerItemCancel').onclick=resetMappingForm;}
