function renderAccountingClearing(){
  finShell('立沖帳查詢',`<div class="desc">立沖查詢同時呈現一般收付款沖帳、預收／預付與溢收／溢付異動、銷退待抵及客戶兼廠商對沖；可依公司別、對象與日期區間追蹤原額、已用、退款、剩餘及分錄底稿。</div><form id="clearingFilter" class="form"><div class="row c4">${selectField('account_type','類別','<option value="">應收／應付</option><option value="AR">應收</option><option value="AP">應付</option>')}${field('party_code','客戶／廠商')}${field('from_date','起日','date')}${field('to_date','迄日','date')}${field('limit','顯示筆數','number','value="200" min="1" max="500"')}<button class="btn primary">查詢立沖</button></div></form><div id="clearingSummary"></div><div class="panel"><div class="panel-head"><span>立沖異動明細</span><button class="btn small" type="button" id="clearingReload">重新整理</button></div><div class="panel-body"><div class="table-wrap"><table class="grid"><thead><tr><th>類型</th><th>單號／關聯</th><th>日期</th><th>對象</th><th>本次金額</th><th>本位幣／匯差</th><th>已用／剩餘</th><th>分錄底稿</th><th>狀態</th></tr></thead><tbody id="clearingRows"></tbody></table></div></div></div>`);
  const amount=value=>esc(value==null?'0':(typeof value==='number'?value:String(value)));
  const summaryCard=(x,label)=>`<div class="panel"><div class="panel-head">${esc(label||`${x.account_type||''}／${x.party_code||''}`)}</div><div class="panel-body">原額 ${amount(x.original_amount)}<br>已用／已沖 ${amount(x.used_amount||x.allocated_amount)}<br>已退款 ${amount(x.refunded_amount)}<br>剩餘 ${amount(x.remaining_amount??x.open_balance)}<br>明細／帳款 ${amount(x.advance_count||x.open_item_count||x.credit_count||0)}</div></div>`;
  const load=async()=>{try{const f=$('#clearingFilter'),d=Object.fromEntries(new FormData(f)),q=new URLSearchParams({source_database:currentDatabase,account_type:d.account_type||'',party_code:d.party_code||'',from_date:d.from_date||'',to_date:d.to_date||'',limit:d.limit||200});const result=await api(`/api/accounting/clearing?${q}`),summary=result.summary||[],advanceSummary=result.advance_summary||[],creditSummary=result.credit_summary||[],crossSummary=result.cross_summary||[];$('#clearingSummary').innerHTML=`<div class="desc">查詢區間：${esc(result.from_date||d.from_date||'不限')} ～ ${esc(result.to_date||d.to_date||'不限')}；來源：${esc(result.source_database||currentDatabase)}</div><div class="row c3">${summary.map(x=>summaryCard(x)).join('')}</div>${advanceSummary.length?`<details class="panel" open><summary class="panel-head">預收／預付與溢收／溢付餘額</summary><div class="panel-body"><div class="row c3">${advanceSummary.map(x=>summaryCard(x,`${x.account_type}／${x.party_code}（立沖）`)).join('')}</div></div></details>`:''}${creditSummary.length?`<details class="panel"><summary class="panel-head">銷退待抵餘額</summary><div class="panel-body"><div class="row c3">${creditSummary.map(x=>summaryCard(x,`${x.party_code}（待抵）`)).join('')}</div></div></details>`:''}${crossSummary.length?`<details class="panel"><summary class="panel-head">客戶兼廠商對沖合計</summary><div class="panel-body"><div class="row c3">${crossSummary.map(x=>`<div class="panel"><div class="panel-head">${esc(x.offset_kind)}</div><div class="panel-body">筆數 ${amount(x.offset_count)}<br>對沖金額 ${amount(x.offset_amount)}<br>匯差 ${amount(x.exchange_difference)}</div></div>`).join('')}</div></div></details>`:''}`;$('#clearingRows').innerHTML=(result.rows||[]).map(x=>{const kind=x.row_kind==='settlement'?'收付款沖帳':x.row_kind==='advance'?'預收／預付':x.row_kind==='customer_credit'?'銷退待抵':'客戶兼廠商對沖',related=x.row_kind==='settlement'?x.related_document_no:x.row_kind==='cross_offset'?`${x.customer_code||''}／${x.supplier_code||''}`:(x.related_document_no||x.reference_no||''),partyValue=x.row_kind==='cross_offset'?`${x.customer_code||''}／${x.supplier_code||''}`:(x.party_code||''),baseValue=x.base_amount??(x.ar_base_amount!=null?`${x.ar_base_amount}／${x.ap_base_amount}`:'—'),used=x.row_kind==='advance'?`${x.movement_kind}／餘 ${x.balance_amount}`:x.row_kind==='customer_credit'?`${x.movement_kind}／餘 ${x.balance_amount}`:x.row_kind==='cross_offset'?x.offset_kind:`已沖 ${x.settled_amount||0}／餘 ${x.balance_amount||0}`,draft=x.accounting_draft_no||'';return `<tr><td>${esc(kind)}</td><td>${esc(x.document_no||'')}<br>${esc(related)}</td><td>${esc(displayDateOf(x.movement_date||x.document_date))}</td><td>${esc(partyValue)}</td><td>${amount(x.amount||x.allocated_amount)}</td><td>${amount(baseValue)}<br>匯差 ${amount(x.exchange_difference)}</td><td>${esc(used)}</td><td>${esc(draft||'—')}</td><td>${esc(x.related_status||x.source_status||'')}</td></tr>`;}).join('')||'<tr><td colspan="9" class="empty-hint">查無立沖異動</td></tr>'; }catch(e){toast(e.message,true);}};$('#clearingFilter').onsubmit=e=>{e.preventDefault();load();};$('#clearingReload').onclick=load;load();
}

