function renderAccountingAutoRules(){
  finShell('自動分錄規則',`<div class="desc">規則依公司別／資料來源獨立維護，來源 ERP 的 ACR／ACP／ACT 只讀。過帳時先依模組、單據種類與單據性質找精確規則，再回退到「*」通用規則。</div>
    <form id="autoRuleForm" class="form"><div class="row c4">${field('rule_code','規則代號','text','required placeholder="例如 AR-SHIPMENT-MAIN"')}${selectField('module_code','模組','<option value="AR">AR 應收</option><option value="AP">AP 應付</option>')}${selectField('document_kind','單據種類','<option value="shipment">銷貨</option><option value="sales_return">銷退</option><option value="purchase_receipt">進貨</option><option value="purchase_return">採購退貨</option><option value="*">通用</option>')}${selectField('entry_role','分錄角色','<option value="main">主分錄</option><option value="cost">成本分錄</option>')}${field('document_type','單據性質','text','value="*"')}${field('debit_account_code','借方科目','text','required')}${field('debit_account_name','借方科目名稱','text','required')}${field('credit_account_code','貸方科目','text','required')}${field('credit_account_name','貸方科目名稱','text','required')}${field('note','說明')}</div><button class="btn primary">新增規則</button></form>
    <div class="panel"><div class="panel-head"><span>目前公司自動分錄規則</span><button class="btn small" id="autoRuleReload" type="button">重新整理</button></div><div class="panel-body"><div class="table-wrap"><table class="grid"><thead><tr><th>規則</th><th>模組／單據</th><th>角色</th><th>借方</th><th>貸方</th><th>狀態</th><th>作業</th></tr></thead><tbody id="autoRuleRows"></tbody></table></div></div></div>`);
  const load=async()=>{try{const rows=await api(`/api/accounting/auto-rules?source_database=${encodeURIComponent(currentDatabase)}`);$('#autoRuleRows').innerHTML=rows.map(x=>`<tr><td>${esc(x.rule_code)}</td><td>${esc(x.module_code)}／${esc(x.document_kind)}／${esc(x.document_type)}</td><td>${esc(x.entry_role)}</td><td>${esc(x.debit_account_code)} ${esc(x.debit_account_name)}</td><td>${esc(x.credit_account_code)} ${esc(x.credit_account_name)}</td><td>${Number(x.is_active)?'啟用':'停用'}</td><td>${Number(x.is_active)?`<button class="btn small" data-rule-disable="${x.id}">停用</button>`:'—'}</td></tr>`).join('')||'<tr><td colspan="7" class="empty-hint">目前尚無自動分錄規則。</td></tr>';document.querySelectorAll('[data-rule-disable]').forEach(b=>b.onclick=async()=>{try{await api(`/api/accounting/auto-rules/${b.dataset.ruleDisable}?source_database=${encodeURIComponent(currentDatabase)}`,{method:'DELETE'});toast('規則已停用');load();}catch(e){toast(e.message,true);}});}catch(e){toast(e.message,true);}};
  $('#autoRuleForm').onsubmit=async e=>{e.preventDefault();try{const d=Object.fromEntries(new FormData(e.currentTarget));d.source_database=currentDatabase;await api('/api/accounting/auto-rules',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)});toast('自動分錄規則已新增');e.currentTarget.reset();e.currentTarget.elements.document_type.value='*';load();}catch(x){toast(x.message,true);}};$('#autoRuleReload').onclick=load;load();
}
function renderAccountingDrafts(){
  if(!window.__accountingDraftActionGuard){document.addEventListener('click',e=>{if(e.target.closest('[data-draft-approve],[data-draft-post],[data-draft-restore]'))e.preventDefault();},true);window.__accountingDraftActionGuard=true;}
  const statusName={draft:'草稿',approved:'已核准',posted:'已拋轉',restored:'已還原'};
  finShell('會計分錄底稿',`<div class="desc">底稿流程固定為「產生 → 只能維護既有行次 → 核准 → 拋轉正式傳票 → 還原」。來源帳款在草稿／核准／已拋轉期間會被鎖定；已拋轉底稿不可還原，必須另建沖回／更正紀錄。</div>
    <div class="panel"><div class="panel-head">1. 從來源帳款產生底稿（可多選，會依科目彙總）</div><div class="panel-body"><form id="draftGenerateForm" class="form"><div class="row c3">${field('draft_date','底稿日期','date',`value="${procurementToday()}" required`)}${field('memo','產生說明','text','placeholder="例如：8 月應收自動分錄"')}<button class="btn primary" type="submit">產生底稿</button></div></form><div class="table-wrap"><table class="grid"><thead><tr><th>選取</th><th>類別</th><th>帳款單號</th><th>日期</th><th>對象</th><th>可立帳餘額</th><th>來源</th><th>狀態</th></tr></thead><tbody id="accountingDraftSourceRows"><tr><td colspan="8">載入中…</td></tr></tbody></table></div></div></div>
    <div class="panel"><div class="panel-head">2. 底稿流程紀錄 <button class="btn small" id="accountingDraftReload" type="button">重新整理</button></div><div class="panel-body"><div class="table-wrap"><table class="grid"><thead><tr><th>底稿號碼</th><th>日期</th><th>來源</th><th>明細</th><th>借方</th><th>貸方</th><th>狀態</th><th>鎖定</th><th>作業</th></tr></thead><tbody id="accountingDraftRows"><tr><td colspan="9">載入中…</td></tr></tbody></table></div></div></div>
    <div id="accountingDraftDetail"></div>`);
  const loadSources=async()=>{try{const rows=await api(`/api/accounting/sources?source_database=${encodeURIComponent(currentDatabase)}&limit=100`);$('#accountingDraftSourceRows').innerHTML=rows.map(x=>`<tr><td><input type="checkbox" data-draft-source value="${esc(x.id)}"></td><td>${esc(x.account_type)}</td><td>${esc(x.document_no)}</td><td>${esc(displayDateOf(x.document_date))}</td><td>${esc(x.party_code)}</td><td>${esc((x.remaining_amount??x.original_amount))}</td><td>${esc(x.source_document_no||x.source_kind||'')}</td><td>${esc(x.status)}</td></tr>`).join('')||'<tr><td colspan="8" class="empty-hint">目前沒有可產生底稿的來源帳款（已鎖定或已拋轉的來源不會重複出現）。</td></tr>';}catch(e){toast(e.message,true);}};
  const action=async(path,body,message)=>{try{await api(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({source_database:currentDatabase,...(body||{})})});toast(message);await load();}catch(e){toast(e.message,true);}};
  const openDetail=async id=>{try{const d=await api(`/api/accounting/drafts/${id}?source_database=${encodeURIComponent(currentDatabase)}`);const rows=d.lines||[];const lineHtml=rows.map(line=>`<tr data-draft-line data-line-no="${esc(line.line_no)}"><td>${esc(line.line_no)}</td><td><input data-line-account value="${esc(line.account_code)}" required><small>${esc(line.account_name)}</small></td><td><input data-line-debit type="number" min="0" step="0.000001" value="${esc(line.debit_amount)}"></td><td><input data-line-credit type="number" min="0" step="0.000001" value="${esc(line.credit_amount)}"></td><td><input data-line-party value="${esc(line.party_code||'')}"></td><td><input data-line-clearing-ref value="${esc(line.clearing_ref||'')}" placeholder="立沖來源"><small>${Number(line.required_clearing)?`必填／${esc(line.clearing_type||'AR/AP')}`:'非立沖科目'}</small></td><td><input data-line-description value="${esc(line.description||'')}"></td></tr>`).join('');const actions=d.status==='draft'?`<button class="btn primary" data-draft-maintain="${d.id}">儲存既有明細</button> <button class="btn" type="button" data-draft-approve="${d.id}">核准</button> <button class="btn" type="button" data-draft-restore="${d.id}">還原</button>`:d.status==='approved'?`<button class="btn primary" type="button" data-draft-post="${d.id}">拋轉正式傳票</button> <button class="btn" data-draft-restore="${d.id}">還原</button>`:'此底稿已完成正式過帳；如需更正請走沖回／更正流程';$('#accountingDraftDetail').innerHTML=`<div class="panel"><div class="panel-head">底稿 ${esc(d.draft_no)}／${esc(statusName[d.status]||d.status)} <span class="code">來源鎖定：${Number(d.source_locked)?'是':'否'}</span></div><div class="panel-body"><div class="desc">來源：${esc((d.sources||[]).map(x=>x.source_document_no||x.source_id).join('、')||'手動底稿')}；借方 ${esc(d.debit_total||0)}／貸方 ${esc(d.credit_total||0)}。${d.status==='draft'?'只能修改下列既有行次，不能新增或刪除。':''}</div><form id="accountingDraftMaintainForm" class="form"><div class="table-wrap"><table class="grid"><thead><tr><th>行次</th><th>科目</th><th>借方</th><th>貸方</th><th>對象</th><th>立沖來源</th><th>說明</th></tr></thead><tbody>${lineHtml}</tbody></table></div><div class="row c3"><input name="reason" placeholder="維護／核准說明" value=""><div>${actions}</div></div></form><details><summary>事件歷程（${(d.events||[]).length} 筆）</summary><div class="table-wrap"><table class="grid"><thead><tr><th>時間</th><th>事件</th><th>狀態</th><th>原因</th></tr></thead><tbody>${(d.events||[]).map(x=>`<tr><td>${esc(displayDateOf(x.created_at))}</td><td>${esc(x.event_kind)}</td><td>${esc(x.before_status||'')} → ${esc(x.after_status||'')}</td><td>${esc(x.reason||'')}</td></tr>`).join('')}</tbody></table></div></details></div></div>`;const form=$('#accountingDraftMaintainForm');if(d.status==='draft')form.onsubmit=async e=>{e.preventDefault();const lines=[...form.querySelectorAll('[data-draft-line]')].map(row=>({line_no:Number(row.dataset.lineNo),account_code:row.querySelector('[data-line-account]').value,debit_amount:Number(row.querySelector('[data-line-debit]').value||0),credit_amount:Number(row.querySelector('[data-line-credit]').value||0),party_code:row.querySelector('[data-line-party]').value,clearing_ref:row.querySelector('[data-line-clearing-ref]').value,description:row.querySelector('[data-line-description]').value,required_clearing:Number((d.lines.find(x=>Number(x.line_no)===Number(row.dataset.lineNo))||{}).required_clearing||0),clearing_type:(d.lines.find(x=>Number(x.line_no)===Number(row.dataset.lineNo))||{}).clearing_type}));try{await api(`/api/accounting/drafts/${d.id}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({source_database:currentDatabase,lines,reason:form.elements.reason.value||'維護底稿'})});toast('底稿既有明細已維護');await openDetail(d.id);await load();}catch(e){toast(e.message,true);}};document.querySelectorAll('[data-draft-approve]').forEach(b=>b.onclick=()=>action(`/api/accounting/drafts/${b.dataset.draftApprove}/approve`,{reason:'核准底稿'},'底稿已核准'));document.querySelectorAll('[data-draft-post]').forEach(b=>b.onclick=()=>action(`/api/accounting/drafts/${b.dataset.draftPost}/post`,{memo:'底稿拋轉正式傳票'},'底稿已拋轉正式傳票'));document.querySelectorAll('[data-draft-restore]').forEach(b=>b.onclick=()=>action(`/api/accounting/drafts/${b.dataset.draftRestore}/restore`,{reason:'底稿還原'},'底稿已還原，來源鎖定已釋放'));}catch(e){toast(e.message,true);}};
  const load=async()=>{try{const rows=await api(`/api/accounting/drafts?source_database=${encodeURIComponent(currentDatabase)}`);$('#accountingDraftRows').innerHTML=rows.map(x=>`<tr><td>${esc(x.draft_no)}</td><td>${esc(displayDateOf(x.draft_date))}</td><td>${esc(x.source_document_no||x.source_kind||'')}</td><td>${esc(x.line_count||0)}</td><td>${esc(x.debit_total||0)}</td><td>${esc(x.credit_total||0)}</td><td>${esc(statusName[x.status]||x.status)}</td><td>${Number(x.source_locked)?'是':'否'}</td><td><button class="btn small" data-draft-open="${x.id}">查看／維護</button></td></tr>`).join('')||'<tr><td colspan="9" class="empty-hint">尚無會計分錄底稿。</td></tr>';document.querySelectorAll('[data-draft-open]').forEach(b=>b.onclick=()=>openDetail(b.dataset.draftOpen));await loadSources();}catch(e){toast(e.message,true);}};
  $('#draftGenerateForm').onsubmit=async e=>{e.preventDefault();const selected=[...document.querySelectorAll('[data-draft-source]:checked')].map(x=>Number(x.value));if(!selected.length){toast('請至少選擇一筆來源帳款',true);return;}const form=e.currentTarget;try{const result=await api('/api/accounting/drafts/generate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({source_database:currentDatabase,source_refs:selected,draft_date:form.elements.draft_date.value,memo:form.elements.memo.value})});toast(`底稿 ${result.draft_no} 已產生並鎖定來源`);form.reset();form.elements.draft_date.value=procurementToday();await load();await openDetail(result.id);}catch(x){toast(x.message,true);}};$('#accountingDraftReload').onclick=load;load();
}
