function flowAuditShell(title,body){$('#canvas').innerHTML=`<section class="screen"><div class="screen-head"><h2>${esc(title)}</h2><span class="code">${esc(targetDatabaseLabel())}</span><button class="btn" id="flowAuditReload" type="button">重新整理</button></div><div class="screen-body"><div class="desc">本頁以 ${esc(currentDatabase)} 的新 ERP 標準資料與財務關聯做唯讀稽核；來源資料庫不回寫。日期範圍套用在各合法起點與補充單據日期，後續已建立的子單據仍會一併追蹤。</div>${body}</div></section>`;}
function flowAuditNumber(value){return flowAmountForView(value).toLocaleString('zh-TW',{maximumFractionDigits:2});}
function flowAmountForView(value){const number=Number(value||0);return Number.isFinite(number)?number:0;}
function flowAuditSummaryTable(summary,kind){const labels=kind==='sales'?[['order_count','訂單張數'],['quote_count','關聯報價張數'],['unconverted_quote_count','未轉訂單報價'],['standalone_shipment_count','獨立銷貨'],['legal_root_count','合法起點筆數'],['orphan_count','孤兒／未關聯'],['supplemental_count','補充單據'],['order_quantity','訂單量'],['delivered_quantity','已銷貨量'],['remaining_quantity','未銷貨量'],['delivered_amount','已銷貨金額'],['returned_amount','銷退／折讓金額'],['billed_amount','已轉應收淨額'],['collected_amount','已收款'],['uncollected_amount','未收款'],['exception_count','異常筆數']]:[['purchase_order_count','採購張數'],['requisition_count','關聯請購張數'],['unconverted_requisition_count','未轉採購請購'],['standalone_receipt_count','獨立進貨'],['purchase_return_count','退貨／折讓明細'],['legal_root_count','合法起點筆數'],['orphan_count','孤兒／未關聯'],['supplemental_count','補充單據'],['order_quantity','採購量'],['accepted_quantity','已驗收量'],['remaining_quantity','待進貨量'],['pending_inspection_quantity','待驗收量'],['pending_inventory_quantity','待入庫量'],['billed_amount','已轉應付'],['paid_amount','已付款'],['unpaid_amount','未付款'],['exception_count','異常筆數']];return `<div class="panel"><div class="panel-head">流程摘要</div><div class="panel-body"><div class="row c3">${labels.map(([key,label])=>`<div><strong>${label}</strong><br>${flowAuditNumber(summary[key])}</div>`).join('')}</div><div class="desc">下一階段筆數：${Object.entries(summary.next_stage||{}).map(([key,value])=>`${esc(key)} ${value} 筆`).join('／')||'查無資料'}</div></div></div>`;}
function flowAuditSupplementalTable(rows){const list=Array.isArray(rows)?rows:[];return `<div class="panel flow-audit-supplemental"><div class="panel-head">合法補充起點／暫出入／轉撥（${list.length} 筆）</div><div class="panel-body"><div class="desc">這些單據不需要先經請購、採購或訂單，仍會納入庫存異動與流程稽核；移轉單的數量變化以來源與目的庫別呈現。</div><div class="table-wrap"><table class="grid"><thead><tr><th>起點／單據</th><th>日期</th><th>單據性質</th><th>品號</th><th>庫別</th><th>數量</th><th>庫存影響</th><th>金額</th><th>下一階段</th><th>異常原因</th><th>稽核</th></tr></thead><tbody>${list.map(row=>`<tr><td><strong>${esc(row.source)}</strong><br><span class="flow-root-tag">${esc(row.root_type||'合法補充起點')}</span></td><td>${esc(displayDateOf(row.document_date))}</td><td>${esc(row.document_type||row.movement_kind)}</td><td>${esc(row.item_code)}<br>${esc(row.item_name)}</td><td>${esc(row.from_warehouse_code||'')} ${row.to_warehouse_code?`→ ${esc(row.to_warehouse_code)}`:''}</td><td>${flowAuditNumber(row.quantity)}</td><td>${flowAuditNumber(row.quantity_delta)}</td><td>${flowAuditNumber(row.amount)}</td><td>${esc(row.next_stage)}</td><td>${esc(row.exception_reason)}</td><td>${esc(row.audit_status)}</td></tr>`).join('')||'<tr><td colspan="11" class="empty-hint">查無合法補充／暫出入／轉撥單據</td></tr>'}</tbody></table></div></div></div>`;}
function renderFlowAuditScreenLegacy(screen){const kind=screen==='purchase-flow-audit'?'procurement':screen==='sales-flow-audit'?'sales':'health';const title=kind==='procurement'?'採購流程稽核（請購→採購→進貨→應付→付款）':kind==='sales'?'銷售流程稽核（報價→訂單→銷貨→應收→收款）':'營運健康度（採購／銷售／應收應付）';let body=flowAuditFiltersLegacy();if(kind==='health')body+=`<div id="flowAuditHealth"></div>`;else body+=`<div id="flowAuditSummary"></div><div id="flowAuditSupplemental"></div><div class="panel"><div class="panel-head">流程明細（起點／來源／各段單據與狀態／剩餘數量／剩餘金額／異常原因）</div><div class="panel-body"><div class="table-wrap"><table class="grid"><thead id="flowAuditHead"></thead><tbody id="flowAuditRows"></tbody></table></div></div></div>`;flowAuditShell(title,body);$('#flowAuditFilter').onsubmit=e=>{e.preventDefault();loadFlowAuditLegacy(kind);};$('#flowAuditReload').onclick=()=>loadFlowAuditLegacy(kind);loadFlowAuditLegacy(kind);}
