function operationsReportValue(value,key){
  if(value===null||value===undefined||value==='')return '—';
  if(['overdue','closed_with_remaining','unclosed','is_unsettled'].includes(key))return Number(value)?'是':'否';
  if(/(^|_)date$/.test(key)||key==='date')return esc(displayDateOf(value));
  if(typeof value==='number'||(/(amount|quantity|count|days|balance|rate|number|price|in|out)$/i.test(key)&&value!==''&&!Number.isNaN(Number(value))))return esc(flowAuditNumber(value));
  if(typeof value==='object')return esc(JSON.stringify(value));
  return esc(value);
}
function operationsReportSummary(summary={}){
  const entries=Object.entries(summary||{}),scalar=entries.filter(([,value])=>value===null||typeof value!=='object'),nested=entries.filter(([,value])=>value&&typeof value==='object');
  const cards=scalar.map(([key,value])=>`<div class="report-summary-card"><span>${esc(operationsReportSummaryLabels[key]||key)}</span><strong>${operationsReportValue(value,key)}</strong></div>`).join('');
  const details=nested.map(([key,value])=>`<details class="report-summary-detail"><summary>${esc(operationsReportSummaryLabels[key]||key)}</summary><pre>${esc(JSON.stringify(value,null,2))}</pre></details>`).join('');
  return `<div class="report-summary-grid">${cards}</div>${details}`;
}
