function renderRejectedReturn(){procurementShell('驗退件退回','PUR-REJECT-RETURN',`<div class="desc">不合格品完成驗收後，記錄實際交還廠商的日期、數量與人員；可分批退回，待退量歸零才算完成。</div>${panelTable('待交還廠商的驗退件',['進貨單','進貨日','廠商','品號','驗退量','已退廠商','待退量','退回日期','退回人員','作業'],'procurementRows')}<div class="panel"><div class="panel-head">最近驗退件退回紀錄</div><div class="panel-body"><div class="table-wrap"><table class="grid"><thead><tr><th>進貨單</th><th>廠商</th><th>品號</th><th>實際退回日</th><th>數量</th><th>人員</th><th>備註</th></tr></thead><tbody id="rejectedReturnHistoryRows"></tbody></table></div></div></div>`);$('#procurementReload').onclick=loadRejectedReturns;loadRejectedReturns();}
