function renderPurchaseReturns(){procurementShell('採購退貨／折讓','PUR-RETURN',`<form id="procurementForm" class="form"><div class="row c3">${selectField('document_type','單別','')}${field('return_no','單號（手動編號時輸入）')}${selectField('return_type','處理方式','<option value="return">退貨</option><option value="allowance">折讓</option>')}${selectField('receipt_item_id','來源進貨','<option value="">載入中</option>')}${field('return_date','日期','text',`value="${procurementToday()}"`)}${field('return_quantity','退貨數量','number','step="0.001" value="0"')}${field('allowance_amount','折讓金額','number','step="0.01" value="0"')}${field('reason','原因','text','required')}</div><button class="btn primary">建立退貨／折讓單</button></form>${panelTable('退貨／折讓紀錄',['單號','日期','類型','廠商','品號','數量','折讓金額','狀態','核準'],'procurementRows')}`);$('#procurementForm').onsubmit=savePurchaseReturn;$('#procurementReload').onclick=loadPurchaseReturns;loadProcurementEntryTypes('returns');loadReturnableReceipts();loadPurchaseReturns();}
